// Admin console (desktop-first): overview, people, network, catalogue, operations, finance, platform.
import { ApiError, ago, api, cap, dateOnly, dt, dtl, esc, getSession, go, html, hoursText, icon, inr, meta, num, openFile, phone, qs, raw, statusInfo } from '../core.js';
import { avatar, barChart, chip, confirmDialog, emptyState, field, hbars, kv, modal, mountTable, note, opts, pageHeader, progress, rowBtn, section, stat, statusChip, tabs, timeline, toast, verified, requestTimeline } from '../ui.js';
import { jobs as jobsPage, complaints as complaintsPage } from './agent.js';

const S = (...p) => p.map(String).join('');
const has = (ctx, p) => (ctx.user.permissions || []).includes(p);
async function act(el, fn) { const l = el.innerHTML; el.disabled = true; el.innerHTML = '<span class="spin"></span>'; try { return await fn(); } catch (e) { toast(e.message || 'Something went wrong', 'error'); } finally { if (el.isConnected) { el.disabled = false; el.innerHTML = l; } } }
async function download(path, filename) {
  const res = await fetch('/api/v1' + path, { headers: { Authorization: 'Bearer ' + getSession('admin').token } });
  if (!res.ok) { const e = await res.json().catch(() => ({})); throw new Error((e.error && e.error.message) || 'Export failed'); }
  const blob = await res.blob(); const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = filename; a.click(); URL.revokeObjectURL(a.href);
}
const catIc = (c, size = 34) => html`<span class="cat-ic" style="background:${c.color || '#E6F4D7'};width:${size}px;height:${size}px;font-size:${Math.round(size * 0.5)}px" aria-hidden="true">${c.icon || '✨'}</span>`;

// ---------------------------------------------------------------- 2. executive dashboard
async function home(ctx) {
  const d = await api('/admin/metrics'); const k = d.kpis;
  return html`${pageHeader('Platform overview', `Today · ${d.city} · All categories`, html`${d.quick_actions.map((a, i) => html`<a class="btn ${i === 0 ? 'btn-primary' : 'btn-ghost'}" href="${a.link}">${a.label}</a>`)}`)}
    <div class="grid g4">${stat({ label: 'Requests today', value: k.requests_today, ic: 'inbox', href: '#/x/requests' })}${stat({ label: 'Completion rate (30d)', value: k.completion_rate != null ? k.completion_rate + '%' : '—', ic: 'check' })}${stat({ label: 'Active verified partners', value: k.active_partners, ic: 'tool', href: '#/x/partners' })}${stat({ label: 'Open escalations', value: k.open_escalations, ic: 'alert', tone: k.open_escalations ? 'warn' : '', href: '#/x/complaints' })}
      ${stat({ label: 'GMV (30d)', value: inr(k.gmv_30d), ic: 'wallet' })}${stat({ label: 'Commission (30d)', value: inr(k.commission_30d), ic: 'trend' })}${stat({ label: 'New customers (7d)', value: k.new_customers_7d, ic: 'users' })}${stat({ label: 'Requests (30d)', value: k.requests_30d, ic: 'chart' })}</div>
    <div class="split mt"><div class="stack"><div class="card"><div class="row between mb"><h2>Request volume — last 14 days</h2></div>${barChart({ labels: d.trend.map((t) => t.label), series: [{ name: 'New requests', color: '#1B231E', values: d.trend.map((t) => t.requests) }, { name: 'Completed', color: '#BEEB5D', values: d.trend.map((t) => t.completed) }] })}</div>
      <div class="grid g2"><div class="card"><h2 class="mb">Top categories (30d)</h2>${d.by_category.length ? hbars(d.by_category.map((c) => ({ label: `${c.icon} ${c.name}`, value: c.n }))) : html`<p class="muted">No data yet.</p>`}</div><div class="card"><h2 class="mb">Open work by stage</h2>${d.by_status.length ? hbars(d.by_status.map((s) => ({ label: s.label, value: s.n })), { color: '#70973E' }) : html`<p class="muted">Nothing open.</p>`}</div></div></div>
    <div class="card"><h2 class="mb">Needs attention</h2>${d.attention.map((a) => html`<a class="list-item" href="${a.link}"><span class="stat-ic ${a.count ? 'tone-warn' : ''}">${icon(a.count ? 'alert' : 'check', 18)}</span><div class="grow"><b>${a.label}</b><div class="muted sm">${a.detail}</div></div><b style="font-size:20px">${a.count}</b>${icon('right', 18, 'chev')}</a>`)}</div></div>`;
}

// ---------------------------------------------------------------- 3. users
async function users(ctx) {
  const roleOpts = ['customer', 'provider', 'employer', 'agent', 'team_lead', 'ops_admin', 'finance_admin', 'verification_reviewer', 'super_admin'].map((r) => [r, cap(r)]);
  let t;
  const detail = async (id) => {
    const u = await api('/admin/users/' + id);
    modal({ title: u.name, footer: false, body: S(`<div class="row-gap">${u.roles.map((r) => chip(cap(r), 'info').toString()).join(' ')} ${chip(cap(u.status), u.status === 'active' ? 'success' : 'danger').toString()}${u.deletion_requested ? chip('Deletion requested', 'warn').toString() : ''}</div>`, kv([['Mobile', u.mobile ? phone(u.mobile) : '—'], ['Email', u.email || '—'], ['Created', dtl(u.created_at)], ['Last sign-in', u.last_login_at ? dtl(u.last_login_at) : 'Never'], ['Requests', u.requests]]).toString(),
      `<h3 class="mt mb">Recent sessions</h3>${u.sessions.map((s) => `<div class="sm muted">${esc(dt(s.created_at))} · ${esc(s.portal)} · ${esc(s.ip || '')}${s.revoked ? ' · revoked' : ''}</div>`).join('') || '<p class="muted sm">None</p>'}<p class="xs muted mt">Viewing this record was added to the audit log.</p><div class="row-gap mt"><button class="btn ${u.status === 'active' ? 'btn-danger-o' : 'btn-primary'}" data-toggle>${u.status === 'active' ? 'Suspend account' : 'Reactivate account'}</button></div>`),
    onMount: (m, close) => m.querySelector('[data-toggle]').addEventListener('click', async () => { const to = u.status === 'active' ? 'suspended' : 'active'; const r = await confirmDialog({ title: `${to === 'suspended' ? 'Suspend' : 'Reactivate'} ${u.name}?`, message: to === 'suspended' ? 'They are signed out everywhere and cannot sign in until reactivated.' : 'They will be able to sign in again.', confirmLabel: cap(to === 'suspended' ? 'suspend' : 'reactivate'), danger: to === 'suspended' }); if (r) { try { await api('/admin/users/' + u.id, { method: 'PATCH', body: { status: to } }); toast('Account updated.'); close(); t.reload(); } catch (e) { toast(e.message, 'error'); } } }) });
  };
  ctx.on('click', '[data-act=add]', () => modal({ title: 'Create staff account', submitLabel: 'Create account', body: S(field({ name: 'name', label: 'Full name', required: true }), field({ name: 'email', label: 'Work email', type: 'email', required: true }), field({ name: 'mobile', label: 'Mobile (optional)', type: 'tel', prefix: '+91' }), field({ name: 'role', label: 'Role', type: 'select', required: true, options: [['', 'Select role'], ['agent', 'Agent'], ['team_lead', 'Team lead'], ['ops_admin', 'Operations admin'], ['finance_admin', 'Finance admin'], ['verification_reviewer', 'Verification reviewer'], ['super_admin', 'Super admin']] }), field({ name: 'password', label: 'Temporary password', type: 'password', required: true, hint: 'At least 8 characters with letters and numbers.', auto: 'new-password' })),
    onSubmit: async (d) => { await api('/admin/users', { method: 'POST', body: d }); toast('Account created.'); t.reload(); } }));
  ctx.after(() => { t = mountTable(ctx.view.querySelector('#tbl'), {
    load: (p) => api('/admin/users' + qs(p)), search: 'Search name, mobile or email', filters: [{ key: 'role', label: 'All roles', options: roleOpts }, { key: 'status', label: 'Any status', options: [['active', 'Active'], ['suspended', 'Suspended']] }],
    columns: [{ label: 'User', render: (u) => html`<b>${u.name}</b><span class="sub">${u.email || phone(u.mobile) || ''}</span>` }, { label: 'Roles', render: (u) => (u.roles || '').split(', ').map((r) => cap(r)).join(', ') }, { label: 'Status', render: (u) => html`${chip(cap(u.status), u.status === 'active' ? 'success' : 'danger')} ${u.deletion_requested ? chip('Deletion requested', 'warn') : ''}` }, { label: 'Last sign-in', render: (u) => (u.last_login_at ? ago(u.last_login_at) : 'Never') }, { label: 'Joined', render: (u) => dateOnly(u.created_at) }, { label: '', cls: 'act', render: () => rowBtn('view', 'View') }],
    actions: { view: (u) => detail(u.id) }, empty: { ic: 'users', title: 'No users match', text: '' },
  }); });
  return html`${pageHeader('User management', 'Manage customer and staff identities.', has(ctx, 'users') ? html`<button class="btn btn-primary" data-act="add">${icon('plus', 18)} Create staff account</button>` : '')}<div id="tbl"></div>`;
}

// ---------------------------------------------------------------- 4. agents
async function agents(ctx) {
  const d = await api('/admin/agents');
  ctx.on('click', '[data-edit]', (e, b) => { const a = d.items.find((x) => x.id === b.dataset.edit); modal({ title: `Edit ${a.name}`, submitLabel: 'Save', body: S(field({ name: 'capacity_limit', label: 'Capacity (active requests)', type: 'number', value: a.capacity_limit, min: 1, hint: `Platform default is ${d.default_capacity}. Validate with pilot data.` }), field({ name: 'availability_status', label: 'Availability', type: 'select', value: a.availability, options: [['available', 'Available'], ['busy', 'Busy'], ['away', 'Away'], ['offline', 'Offline']] }), field({ name: 'specialty', label: 'Specialty', value: a.specialty || '' }), `<label class="check"><input type="checkbox" name="is_pool" ${a.is_pool ? 'checked' : ''}><span>Include in the hybrid pool (overflow and new customers)</span></label>`), onSubmit: async (x) => { await api('/admin/agents/' + a.id, { method: 'PATCH', body: x }); toast('Agent updated.'); ctx.reload(); } }); });
  ctx.on('click', '[data-act=add]', () => modal({ title: 'Create agent', submitLabel: 'Create agent', body: S(field({ name: 'name', label: 'Full name', required: true }), field({ name: 'email', label: 'Work email', type: 'email', required: true }), field({ name: 'mobile', label: 'Mobile', type: 'tel', prefix: '+91' }), field({ name: 'role', label: 'Role', type: 'select', options: [['agent', 'Agent'], ['team_lead', 'Team lead']] }), field({ name: 'specialty', label: 'Specialty' }), field({ name: 'password', label: 'Temporary password', type: 'password', required: true, auto: 'new-password' })), onSubmit: async (x) => { await api('/admin/users', { method: 'POST', body: x }); toast('Agent created.'); ctx.reload(); } }));
  const over = d.items.filter((a) => a.active_requests >= a.capacity_limit).length;
  return html`${pageHeader('Agent management', 'Manage dedicated agents, supervisors and hybrid allocation.', html`<a class="btn btn-ghost" href="#/x/assignment">Assignment rules</a>${has(ctx, 'users') ? html`<button class="btn btn-primary" data-act="add">${icon('plus', 18)} Create agent</button>` : ''}`)}
    ${over ? note(`${over} agent(s) are at or above capacity. New requests overflow to backup and pool agents.`, 'warn') : ''}
    <div class="table-wrap mt"><table class="table"><thead><tr><th>Agent</th><th>Specialty</th><th class="num">Customers</th><th>Workload</th><th>Availability</th><th>Pool</th><th class="num">Rating</th><th></th></tr></thead><tbody>${d.items.map((a) => { const pct = Math.round((a.active_requests * 100) / a.capacity_limit); return html`<tr><td data-label="Agent"><b>${a.name}</b> ${(a.roles || '').includes('team_lead') ? chip('Team lead', 'lime') : ''}<span class="sub">${a.email}</span></td><td data-label="Specialty">${a.specialty || '—'}</td><td class="num" data-label="Customers">${a.customers}</td><td data-label="Workload"><div class="bar-line"><div class="gauge ${pct >= 100 ? 'hot' : pct > 70 ? 'warm' : ''}" style="flex:1"><i style="width:${Math.min(100, pct)}%"></i></div><span class="sm">${a.active_requests}/${a.capacity_limit}</span></div></td><td data-label="Availability">${chip(cap(a.availability), a.availability === 'available' ? 'success' : 'warn')}</td><td data-label="Pool">${a.is_pool ? 'Yes' : 'No'}</td><td class="num" data-label="Rating">${a.rating || '—'}</td><td class="act">${has(ctx, 'agents') ? html`<button class="btn btn-ghost btn-sm" data-edit="${a.id}">Edit</button>` : ''}</td></tr>`; })}</tbody></table></div>`;
}

// ---------------------------------------------------------------- 5. assignment rules
async function assignment(ctx) {
  const [d, ag] = await Promise.all([api('/admin/assignment'), api('/agents')]);
  ctx.on('change', '[data-rule]', async (e, el) => { try { await api('/admin/assignment/rules/' + el.dataset.rule, { method: 'PUT', body: { active: el.checked } }); toast(el.checked ? 'Rule enabled.' : 'Rule disabled.'); } catch (err) { el.checked = !el.checked; toast(err.message, 'error'); } });
  ctx.on('click', '[data-act=reassign]', () => modal({ title: 'Reassign a customer', wide: true, submitLabel: 'Reassign customer', body: S(note('Reassignment is recorded with reason, who changed it and when. The customer sees their new agent.', 'info'), '<div class="mt"></div>', field({ name: 'cq', label: 'Find customer (name or mobile)', placeholder: 'Type to search…' }), '<div id="cres" class="stack mb"></div><input type="hidden" name="customer_id">', html`<div class="grid g2">${field({ name: 'primary_agent_id', label: 'New primary agent', type: 'select', required: true, options: [['', 'Select'], ...ag.items.map((a) => [a.id, `${a.name} (${a.active_requests}/${a.capacity_limit})`])] })}${field({ name: 'backup_agent_id', label: 'Backup agent', type: 'select', options: [['', 'None'], ...ag.items.map((a) => [a.id, a.name])] })}</div>`, field({ name: 'reason', label: 'Reason', required: true, placeholder: 'e.g. Agent on leave for two weeks' }), `<label class="check"><input type="checkbox" name="move_open_requests" checked><span>Also move this customer's open requests to the new agent</span></label>`),
    onMount: (m) => { const cq = m.querySelector('[name=cq]'); const res = m.querySelector('#cres'); let timer; cq.addEventListener('input', () => { clearTimeout(timer); timer = setTimeout(async () => { if (cq.value.trim().length < 2) { res.innerHTML = ''; return; } const r = await api('/admin/users?role=customer&page_size=5&q=' + encodeURIComponent(cq.value)); res.innerHTML = r.items.map((u) => `<button type="button" class="btn btn-ghost btn-block" data-pick="${esc(u.id)}" style="justify-content:flex-start">${esc(u.name)} <span class="muted sm">${esc(u.mobile || '')}</span></button>`).join('') || '<p class="muted sm">No customer found.</p>'; }, 300); });
      res.addEventListener('click', (e) => { const b = e.target.closest('[data-pick]'); if (b) { m.querySelector('[name=customer_id]').value = b.dataset.pick; res.innerHTML = `<div class="note note-success">Selected: ${b.firstChild.textContent}</div>`; } }); },
    onSubmit: async (x) => { if (!x.customer_id) throw new ApiError(422, 'validation', 'Choose a customer first.', { cq: 'Search and select a customer.' }); const r = await api(`/admin/customers/${x.customer_id}/reassign`, { method: 'POST', body: { primary_agent_id: x.primary_agent_id, backup_agent_id: x.backup_agent_id || undefined, reason: x.reason, move_open_requests: x.move_open_requests } }); toast(`Customer reassigned (${r.moved_requests} open request(s) moved).`); ctx.reload(); } }));
  return html`${pageHeader('Assignment rules', 'Configure dedicated primary and hybrid overflow routing.', has(ctx, 'assignment') ? html`<button class="btn btn-primary" data-act="reassign">${icon('refresh', 18)} Reassign a customer</button>` : '')}
    <div class="split"><div class="stack"><div class="card"><h2 class="mb">Routing rules</h2>${d.rules.map((r) => html`<div class="list-item"><div class="grow"><b>${r.name}</b> <span class="chip chip-neutral">Priority ${r.priority}</span><div class="muted sm">${r.description}</div></div><label class="switch-row" style="padding:0;border:0"><span class="visually-hidden">Enabled</span><input type="checkbox" role="switch" data-rule="${r.id}" ${r.active ? 'checked' : ''} ${has(ctx, 'assignment') ? '' : 'disabled'}><i></i></label></div>`)}</div>
      <div class="card"><h2 class="mb">Assignment history</h2>${d.history.length ? html`<div class="table-wrap"><table class="table"><thead><tr><th>When</th><th>Customer</th><th>From → To</th><th>Reason</th></tr></thead><tbody>${d.history.map((h) => html`<tr><td data-label="When">${dt(h.changed_at)}</td><td data-label="Customer">${h.customer_name}${h.reference ? html`<span class="sub">${h.reference}</span>` : ''}</td><td data-label="Route">${h.from_name || '—'} → <b>${h.to_name || 'Unassigned'}</b></td><td data-label="Reason">${h.reason}</td></tr>`)}</tbody></table></div>` : html`<p class="muted">No history yet.</p>`}</div></div>
    <div class="stack"><div class="card"><h2 class="mb">Capacity</h2><div class="price-big">${d.default_capacity}</div><p class="muted sm">Default active requests per agent. This is a <b>setting</b>, not a hard-coded number — validate it with pilot data in <a href="#/x/settings">Settings</a>.</p></div>
      <div class="card"><h2 class="mb">Pool</h2>${kv([['Unassigned requests', d.unassigned]])}<a class="btn btn-ghost btn-block mt" href="#/x/requests?scope=pool">View pool</a></div></div></div>`;
}

// ---------------------------------------------------------------- 6. partners
async function partners(ctx) {
  const [cats, m] = await Promise.all([api('/categories'), meta()]); let t;
  const view = async (id) => {
    const p = await api('/providers/' + id);
    modal({ title: p.business_name, wide: true, footer: false, body: S(`<div class="row-gap" style="gap:8px">${verified(p.verification_status).toString()} ${chip(cap(p.status), p.status === 'active' ? 'success' : 'danger').toString()} ${chip(cap(p.source.replace('_', ' '))).toString()}</div>`, `<div class="split mt"><div>${kv([['Contact', p.phone ? phone(p.phone) : '—'], ['Email', p.email || '—'], ['Locality', p.locality], ['Rating', p.rating_avg ? `${p.rating_avg} (${p.rating_count})` : '—'], ['Jobs', p.jobs_completed], ['Areas', p.areas.join(', ')]]).toString()}</div><div><h3 class="mb">Documents</h3>${p.documents.map((d) => `<div class="row between sm" style="padding:3px 0"><span>${esc(cap(d.doc_type))} ${d.doc_number ? '<span class="muted">' + esc(d.doc_number) + '</span>' : ''}</span><span class="chip chip-${d.status === 'verified' ? 'success' : d.status === 'pending' ? 'warn' : 'danger'}">${esc(d.status)}</span></div>`).join('') || '<p class="muted">None</p>'}</div></div><div class="row-gap mt">${has(ctx, 'partners') ? `<button class="btn ${p.status === 'active' ? 'btn-danger-o' : 'btn-primary'}" data-sus>${p.status === 'active' ? 'Suspend partner' : 'Reinstate partner'}</button>` : ''}${p.verification_status !== 'verified' ? '<a class="btn btn-secondary" href="#/x/verification">Go to verification queue</a>' : ''}</div>`),
      onMount: (mm, close) => mm.querySelector('[data-sus]')?.addEventListener('click', async () => { const sus = p.status === 'active'; const r = await confirmDialog({ title: `${sus ? 'Suspend' : 'Reinstate'} ${p.business_name}?`, message: sus ? 'They stop receiving leads and cannot quote until reinstated.' : 'They can receive leads again.', confirmLabel: sus ? 'Suspend' : 'Reinstate', danger: sus, reason: sus ? 'required' : false }); if (r) { try { await api(`/providers/${p.id}/suspend`, { method: 'POST', body: { suspend: sus, reason: r.reason } }); toast('Partner updated.'); close(); t.reload(); } catch (e) { toast(e.message, 'error'); } } }) });
  };
  ctx.after(() => { t = mountTable(ctx.view.querySelector('#tbl'), {
    load: (p) => api('/providers' + qs(p)), search: 'Search partner or phone', filters: [{ key: 'verification_status', label: 'Any verification', options: [['verified', 'Verified'], ['pending', 'Pending'], ['unverified', 'Unverified'], ['rejected', 'Rejected']] }, { key: 'status', label: 'Any status', options: [['active', 'Active'], ['suspended', 'Suspended']] }, { key: 'category_id', label: 'All categories', options: cats.items.map((c) => [c.id, c.name]) }, { key: 'kind', label: 'All types', options: [['general', 'General'], ['catering', 'Catering'], ['photography', 'Photography']] }],
    columns: [{ label: 'Partner', render: (p) => html`<div class="row">${avatar(p.business_name, p.logo_color, 34)}<div><b>${p.business_name}</b><span class="sub">${p.categories || ''}</span></div></div>` }, { label: 'Verification', render: (p) => html`${verified(p.verification_status)}${p.docs_pending ? html`<span class="sub">${p.docs_pending} doc(s) pending</span>` : ''}` }, { label: 'Status', render: (p) => chip(cap(p.status), p.status === 'active' ? 'success' : 'danger') },
      { label: 'Rating', render: (p) => (p.rating_avg ? `${p.rating_avg} (${p.rating_count})` : '—') }, { label: 'Jobs', cls: 'num', render: (p) => p.jobs_completed }, { label: 'Source', render: (p) => cap(p.source.replace('_', ' ')) }, { label: '', cls: 'act', render: () => rowBtn('view', 'View') }],
    actions: { view: (p) => view(p.id) }, empty: { ic: 'tool', title: 'No partners match', text: '' },
  }); if (ctx.query.open) view(ctx.query.open); });
  return html`${pageHeader('Partner management', 'Manage partner lifecycle and trust status.')}<div id="tbl"></div>`;
}

// ---------------------------------------------------------------- 7. verification queue
async function verification(ctx) {
  const d = await api('/admin/verification-queue');
  ctx.on('click', '[data-act=open-file]', (e, b) => b.dataset.id && openFile(b.dataset.id));
  ctx.on('click', '[data-doc]', (e, b) => {
    const [id, st] = b.dataset.doc.split(':');
    if (st === 'verified') act(b, async () => { await api(`/provider-documents/${id}/review`, { method: 'POST', body: { status: 'verified' } }); toast('Document verified.'); ctx.reload(); });
    else modal({ title: 'Reject document', danger: true, submitLabel: 'Reject', body: field({ name: 'note', label: 'What should the partner fix?', type: 'textarea', required: true }).toString(), onSubmit: async (x) => { await api(`/provider-documents/${id}/review`, { method: 'POST', body: { status: 'rejected', note: x.note } }); toast('Document rejected.'); ctx.reload(); } });
  });
  ctx.on('click', '[data-prov]', (e, b) => {
    const [id, action] = b.dataset.prov.split(':');
    if (action === 'approve') act(b, async () => { await api(`/providers/${id}/verify`, { method: 'POST', body: { action: 'approve' } }); toast('Partner verified.'); ctx.reload(); });
    else modal({ title: 'Reject verification', danger: true, submitLabel: 'Reject', body: field({ name: 'note', label: 'Reason', type: 'textarea', required: true }).toString(), onSubmit: async (x) => { await api(`/providers/${id}/verify`, { method: 'POST', body: { action: 'reject', note: x.note } }); toast('Verification rejected.'); ctx.reload(); } });
  });
  ctx.on('click', '[data-emp]', (e, b) => act(b, async () => { const [id, a] = b.dataset.emp.split(':'); await api(`/employers/${id}/verify`, { method: 'POST', body: { action: a } }); toast('Employer updated.'); ctx.reload(); }));
  return html`${pageHeader('Partner verification queue', 'Approve verification based on evidence. Unverified partners are never shown as verified.')}
    ${d.providers.length ? d.providers.map((p) => html`<div class="card mb"><div class="row between wrap"><div><h2>${p.business_name}</h2><div class="muted sm">${p.owner || 'Directory listing'} ${p.mobile ? '· ' + phone(p.mobile) : ''} · ${p.locality} · ${cap(p.source.replace('_', ' '))} · registered ${ago(p.created_at)}</div></div><div class="row-gap">${verified(p.verification_status)}<button class="btn btn-primary btn-sm" data-prov="${p.id}:approve">Approve partner</button><button class="btn btn-ghost btn-sm" data-prov="${p.id}:reject">Reject</button></div></div>
      <div class="mt">${p.documents.map((x) => html`<div class="doc-row"><span class="stat-ic">${icon('file', 18)}</span><div class="grow"><b>${cap(x.doc_type)}</b> ${x.doc_number ? html`<span class="muted">${x.doc_number}</span>` : ''}<div class="muted sm">Uploaded ${ago(x.created_at)}${x.review_note ? ' · ' + x.review_note : ''}</div></div>${chip(cap(x.status), { verified: 'success', pending: 'warn', rejected: 'danger' }[x.status] || 'neutral')}${x.attachment_id ? html`<button class="btn btn-ghost btn-sm" data-act="open-file" data-id="${x.attachment_id}">View</button>` : html`<span class="muted xs">No file</span>`}${x.status === 'pending' ? html`<button class="btn btn-primary btn-sm" data-doc="${x.id}:verified">Verify</button><button class="btn btn-ghost btn-sm" data-doc="${x.id}:rejected">Reject</button>` : ''}</div>`)}</div></div>`) : emptyState({ ic: 'shield', title: 'No partners waiting', text: 'New partner KYC submissions appear here.' })}
    ${d.employers.length ? section('Employers to verify', html`<div class="card" style="padding:4px 16px">${d.employers.map((e) => html`<div class="list-item"><div class="grow"><b>${e.company_name}</b><div class="muted sm">${e.industry} · ${e.locality} · ${e.contact_name} ${phone(e.phone)}</div></div><button class="btn btn-primary btn-sm" data-emp="${e.id}:verify">Verify</button><button class="btn btn-ghost btn-sm" data-emp="${e.id}:reject">Reject</button></div>`)}</div>`) : ''}`;
}

// ---------------------------------------------------------------- 8. categories
async function categories(ctx) {
  const d = await api('/admin/categories');
  const form = (c) => S(field({ name: 'name', label: 'Name', value: c.name, required: true }), field({ name: 'description', label: 'Description', type: 'textarea', rows: 2, value: c.description || '' }),
    html`<div class="grid g2">${field({ name: 'module_id', label: 'Module', type: 'select', value: c.module_id, options: d.modules.map((m) => [m.id, m.name]) })}${field({ name: 'workflow_template_id', label: 'Workflow template', type: 'select', value: c.workflow_template_id || '', options: d.workflows.map((w) => [w.id, w.name]) })}${field({ name: 'phase', label: 'Release phase', type: 'number', value: c.phase, min: 1, max: 8, hint: 'Phase 1-8 per the rollout plan' })}</div>`,
    field({ name: 'schema', label: 'Request form fields (JSON)', type: 'textarea', rows: 6, value: JSON.stringify(c.schema || [], null, 1), hint: 'Each field: key, label, type (text, textarea, select, number, date), required, options. Changes apply instantly — no code change.' }), `<label class="check"><input type="checkbox" name="is_active" ${c.is_active ? 'checked' : ''}><span>Live — customers can create requests in this category</span></label>`);
  const save = async (id, d_) => { let schema; try { schema = JSON.parse(d_.schema || '[]'); } catch { throw new ApiError(422, 'validation', 'The form fields are not valid JSON.', { schema: 'Not valid JSON.' }); } await api('/admin/categories/' + id, { method: 'PATCH', body: { name: d_.name, description: d_.description, module_id: d_.module_id, workflow_template_id: d_.workflow_template_id, phase: d_.phase, is_active: d_.is_active, schema } }); };
  ctx.on('click', '[data-edit]', (e, b) => { const c = d.items.find((x) => x.id === b.dataset.edit); modal({ title: 'Edit category', wide: true, body: form(c), onSubmit: async (x) => { await save(c.id, x); toast('Category updated.'); ctx.reload(); } }); });
  ctx.on('change', '[data-live]', async (e, el) => { try { await api('/admin/categories/' + el.dataset.live, { method: 'PATCH', body: { is_active: el.checked } }); toast(el.checked ? 'Category is now live.' : 'Category hidden from customers.'); } catch (err) { el.checked = !el.checked; toast(err.message, 'error'); } });
  ctx.on('click', '[data-act=add]', () => modal({ title: 'Add category', submitLabel: 'Create category', body: S(field({ name: 'name', label: 'Name', required: true }), field({ name: 'module_id', label: 'Module', type: 'select', required: true, options: d.modules.map((m) => [m.id, m.name]) }), field({ name: 'phase', label: 'Release phase', type: 'number', value: 8, min: 1, max: 8 }), field({ name: 'description', label: 'Description', type: 'textarea', rows: 2 })), onSubmit: async (x) => { await api('/admin/categories', { method: 'POST', body: x }); toast('Category created (hidden until you switch it live).'); ctx.reload(); } }));
  const live = d.items.filter((c) => c.is_active).length;
  return html`${pageHeader('Category management', `Configure all ${d.items.length} categories and phased availability. ${live} live.`, has(ctx, 'catalogue') ? html`<button class="btn btn-primary" data-act="add">${icon('plus', 18)} Add category</button>` : '')}
    ${note('Do not launch every category at once: switch categories live as quality and unit economics are proven (see the phased rollout plan).', 'info')}
    <div class="table-wrap mt"><table class="table"><thead><tr><th>Category</th><th>Module</th><th>Phase</th><th>Workflow</th><th class="num">Requests</th><th class="num">Providers</th><th>Live</th><th></th></tr></thead><tbody>${d.items.map((c) => html`<tr><td data-label="Category"><div class="row">${catIc(c)}<div><b>${c.name}</b><span class="sub">${c.schema.length} form field(s)</span></div></div></td><td data-label="Module">${c.module_name}</td><td data-label="Phase">${chip('Phase ' + c.phase)}</td><td data-label="Workflow">${c.workflow_name}</td><td class="num" data-label="Requests">${c.requests}</td><td class="num" data-label="Providers">${c.providers}</td><td data-label="Live"><label class="switch-row" style="padding:0;border:0"><span class="visually-hidden">Live</span><input type="checkbox" role="switch" data-live="${c.id}" ${c.is_active ? 'checked' : ''} ${has(ctx, 'catalogue') ? '' : 'disabled'}><i></i></label></td><td class="act">${has(ctx, 'catalogue') ? html`<button class="btn btn-ghost btn-sm" data-edit="${c.id}">Edit</button>` : ''}</td></tr>`)}</tbody></table></div>`;
}

// ---------------------------------------------------------------- 9. workflows
async function workflows(ctx) {
  const d = await api('/admin/workflows');
  const cur = d.items.find((w) => w.id === ctx.query.t) || d.items[0];
  ctx.submit('#f-wf', async (x) => {
    const steps = cur.steps.map((s) => ({ status_key: s.status_key, label: x['l_' + s.status_key], sla_hours: x['h_' + s.status_key], approval_gate: s.status_key === 'awaiting_approval' ? true : !!x['g_' + s.status_key] }));
    await api('/admin/workflows/' + cur.id, { method: 'PUT', body: { name: x.name, description: x.description, stages: x.stages.split('\n').map((s) => s.trim()).filter(Boolean), steps } }); toast('Workflow saved.'); ctx.reload();
  });
  return html`${pageHeader('Workflow builder', 'Manage category-specific request states, SLAs and approval gates without code changes.')}
    ${raw(tabs(d.items.map((w) => [w.id, w.name]), cur.id, '#/x/workflows').toString().replace(/\?tab=/g, '?t='))}
    <form id="f-wf" class="card mt" novalidate><div class="split"><div>${field({ name: 'name', label: 'Template name', value: cur.name, required: true })}${field({ name: 'description', label: 'Description', value: cur.description || '' })}${field({ name: 'stages', label: 'Customer-facing stages (one per line)', type: 'textarea', rows: 6, value: cur.stages.join('\n') })}<p class="muted sm">Used by: ${cur.categories.map((c) => c.name).join(', ') || 'no categories'}</p></div>
      <div><h3 class="mb">States, SLAs & gates</h3><div class="table-wrap"><table class="table"><thead><tr><th>State</th><th>Label</th><th>SLA (hrs)</th><th>Gate</th></tr></thead><tbody>${cur.steps.map((s) => html`<tr><td data-label="State">${chip(statusInfo(s.status_key).label)}</td><td data-label="Label"><input name="l_${s.status_key}" value="${s.label}" aria-label="${s.status_key} label" style="min-height:36px"></td><td data-label="SLA"><input name="h_${s.status_key}" type="number" min="1" max="720" value="${s.sla_hours}" aria-label="${s.status_key} SLA hours" style="min-height:36px;width:90px"></td><td data-label="Gate">${s.status_key === 'awaiting_approval' ? html`<span title="Customer approval is a mandatory hard gate">${icon('lock', 16)} Required</span>` : html`<input type="checkbox" name="g_${s.status_key}" ${s.approval_gate ? 'checked' : ''} aria-label="Approval gate for ${s.status_key}">`}</td></tr>`)}</tbody></table></div>
        <p class="muted xs mt">Requests that sit in a state longer than its SLA are flagged overdue in the agent and admin queues. The customer-approval gate before booking cannot be disabled.</p></div></div>
      <div class="form-error" role="alert" hidden></div>${has(ctx, 'catalogue') ? html`<button class="btn btn-primary" type="submit">Save workflow</button>` : ''}</form>`;
}

// ---------------------------------------------------------------- 10. requests
async function requests(ctx) {
  const m = await meta(); const [cats, ag] = await Promise.all([api('/categories'), api('/agents')]); let t;
  const detail = async (id) => {
    const r = await api('/requests/' + id);
    modal({ title: `${r.reference} · ${r.title}`, wide: true, footer: false, body: S(`<div class="row-gap" style="gap:8px">${statusChip(r.status, r.status_label).toString()} ${r.priority === 'urgent' ? chip('Urgent', 'danger').toString() : ''} ${chip(r.agent ? 'Agent ' + r.agent.name : 'Unassigned', r.agent ? 'info' : 'warn').toString()}</div><p class="mt">${esc(r.description)}</p>`, kv([['Customer', r.customer.name], ['Area', r.locality], ['Created', dtl(r.created_at)], ['Quotes', `${r.quotes.length} (${r.quotes.filter((q) => ['shared', 'approved'].includes(q.status)).length} shared/approved)`], ['Booking', r.booking ? `${r.booking.reference} · ${inr(r.booking.amount)}` : '—']]).toString(), `<h3 class="mt mb">Timeline</h3>${requestTimeline(r.history, r.status).toString()}<div class="row-gap mt"><button class="btn btn-secondary" data-re>Reassign</button></div>`),
      onMount: (mm, close) => mm.querySelector('[data-re]').addEventListener('click', () => { close(); reassign(r); }) });
  };
  const reassign = (r) => modal({ title: `Reassign ${r.reference}`, submitLabel: 'Reassign', body: S(field({ name: 'agent_id', label: 'New owner', type: 'select', required: true, options: [['', 'Select an agent'], ...ag.items.filter((a) => a.id !== r.assigned_agent_id).map((a) => [a.id, `${a.name} · ${a.active_requests}/${a.capacity_limit} · ${a.availability}`])] }), field({ name: 'reason', label: 'Reason', required: true, value: 'Rebalanced by operations' })), onSubmit: async (d) => { await api(`/requests/${r.id}/assign`, { method: 'POST', body: d }); toast('Request reassigned.'); t.reload(); } });
  ctx.after(() => { t = mountTable(ctx.view.querySelector('#tbl'), {
    load: (p) => api('/requests' + qs({ ...p, scope: ctx.query.scope })), initial: { q: ctx.query.q || '' }, search: 'Search reference, title or customer', pageSize: 12,
    filters: [{ key: 'status', label: 'All statuses', options: m.statuses.map((s) => [s.key, s.label]) }, { key: 'category_id', label: 'All categories', options: cats.items.map((c) => [c.id, c.name]) }, { key: 'agent_id', label: 'Any agent', options: ag.items.map((a) => [a.id, a.name]) }, { key: 'sla', label: 'Any SLA', options: [['overdue', 'SLA overdue']] }],
    columns: [{ label: 'Request', render: (r) => html`<b>${r.reference}</b> ${r.priority === 'urgent' ? chip('Urgent', 'danger') : ''}<span class="sub">${r.title}</span>` }, { label: 'Customer', render: (r) => r.customer_name }, { label: 'Area', render: (r) => r.locality }, { label: 'Status', render: (r) => statusChip(r.status, r.status_label) },
      { label: 'Age', render: (r) => (r.overdue ? chip('SLA overdue', 'danger') : hoursText(r.age_hours)) }, { label: 'Owner', render: (r) => r.agent_name || chip('Unassigned', 'warn') }, { label: '', cls: 'act', render: () => html`${rowBtn('view', 'View')}${rowBtn('re', 'Reassign')}` }],
    actions: { view: (r) => detail(r.id), re: (r) => reassign(r) }, empty: { ic: 'inbox', title: 'No requests match', text: '' },
  }); });
  return html`${pageHeader('Request management', 'Global operational view of every request and its owner.')}${ctx.query.scope === 'pool' ? note('Showing only unassigned requests (the pool). Reassign them to an agent.', 'warn') : ''}<div id="tbl" class="mt"></div>`;
}

// ---------------------------------------------------------------- 11. oversight
async function oversight(ctx) {
  const d = await api('/admin/oversight');
  const block = (title, list, empty, render) => section(title, list.length ? html`<div class="card" style="padding:4px 16px">${list.map(render)}</div>` : html`<p class="muted">${empty}</p>`);
  return html`${pageHeader('Quote & booking oversight', 'Monitor approval, booking and cancellation controls.')}
    <div class="grid g4">${stat({ label: 'Quotes shared', value: d.stats.quotes_shared, ic: 'file' })}${stat({ label: 'Quotes approved', value: d.stats.quotes_approved, ic: 'check' })}${stat({ label: 'Live bookings', value: d.stats.bookings_live, ic: 'briefcase' })}${stat({ label: 'Disputed', value: d.disputed.length, ic: 'alert', tone: d.disputed.length ? 'warn' : '' })}</div>
    <div class="card card-soft mt"><b>${icon('lock', 16)} Controls enforced by the platform</b><ul style="margin:6px 0 0;padding-left:18px"><li>${d.stats.approval_gate}. Quote changes after approval require renewed consent.</li><li>${d.stats.duplicate_guard}.</li><li>Every status change records actor, time and reason.</li></ul></div>
    ${block('Awaiting customer approval', d.stale_approvals, 'None waiting.', (r) => html`<div class="list-item"><div class="grow"><b>${r.reference}</b> · ${r.title}<div class="muted sm">${r.customer_name} · agent ${r.agent_name || '—'}</div></div>${r.waiting_hours > 48 ? chip(hoursText(r.waiting_hours), 'danger') : chip(hoursText(r.waiting_hours))}</div>`)}
    ${block('Revised quotes awaiting re-consent', d.reconsent, 'None.', (b) => html`<div class="list-item"><div class="grow"><b>${b.reference}</b> · ${b.business_name}<div class="muted sm">${b.request_reference}</div></div><b>${inr(b.amount)}</b></div>`)}
    ${block('Confirmed bookings with no payment', d.unpaid, 'None.', (b) => html`<div class="list-item"><div class="grow"><b>${b.reference}</b> · ${b.business_name}<div class="muted sm">Scheduled ${b.scheduled_at ? dt(b.scheduled_at) : 'TBC'}</div></div><b>${inr(b.amount)}</b></div>`)}
    ${block('Recent cancellations', d.cancellations, 'None.', (b) => html`<div class="list-item"><div class="grow"><b>${b.reference}</b> · ${b.business_name}<div class="muted sm">${b.cancel_reason || 'No reason recorded'} · ${ago(b.updated_at)}</div></div>${b.paid_amount ? chip(`${inr(b.paid_amount)} paid · refund ${b.refund_eligible ? 'eligible' : 'not eligible'}`, b.refund_eligible ? 'warn' : 'neutral') : ''}</div>`)}
    ${d.disputed.length ? block('Disputed bookings', d.disputed, '', (b) => html`<div class="list-item"><div class="grow"><b>${b.reference}</b> · ${b.business_name}<div class="muted sm">${b.request_reference}</div></div>${chip('Disputed', 'danger')}</div>`) : ''}`;
}

// ---------------------------------------------------------------- 13. finance
async function finance(ctx) {
  const tab = ctx.query.tab || 'transactions'; const s = await api('/admin/finance/summary'); let t;
  const decideRefund = (f, action) => act2(async () => { await api(`/admin/finance/refunds/${f.id}/decide`, { method: 'POST', body: { action } }); toast(action === 'approve' ? 'Refund processed.' : 'Refund rejected.'); t.reload(); });
  const act2 = async (fn) => { try { await fn(); } catch (e) { toast(e.message, 'error'); } };
  ctx.on('click', '[data-act=rule]', () => modal({ title: 'New commission rule (versioned)', submitLabel: 'Publish rule', body: S(note(`Current: v${s.commission_rule.version} at ${s.commission_rule.rate}%. Rules apply to bookings completed after this moment; earlier ledger entries are never rewritten.`, 'info'), '<div class="mt"></div>', field({ name: 'rate', label: 'Commission rate (%)', type: 'number', step: '0.1', min: 0, max: 40, required: true, value: s.commission_rule.rate }), field({ name: 'note', label: 'Why is this changing?', required: true })), onSubmit: async (x) => { await api('/admin/finance/commission-rules', { method: 'POST', body: x }); toast('Commission rule published.'); ctx.reload(); } }));
  ctx.after(() => {
    const el = ctx.view.querySelector('#tbl'); if (!el) return;
    if (tab === 'transactions') t = mountTable(el, { load: (p) => api('/admin/finance/transactions' + qs(p)), search: 'Search reference, user or booking', filters: [{ key: 'kind', label: 'All types', options: [['customer_payment', 'Customer payments'], ['membership', 'Membership'], ['refund', 'Refunds']] }, { key: 'status', label: 'Any status', options: [['success', 'Success'], ['failed', 'Failed']] }],
      columns: [{ label: 'Reference', render: (x) => html`<b>${x.reference}</b><span class="sub">${dt(x.created_at)}</span>` }, { label: 'User', render: (x) => x.user_name }, { label: 'Booking', render: (x) => x.booking_reference || '—' }, { label: 'Type', render: (x) => cap(x.kind.replace('_', ' ')) }, { label: 'Method', render: (x) => x.method || '—' }, { label: 'Amount', cls: 'num', render: (x) => inr(x.amount) }, { label: 'Status', render: (x) => chip(cap(x.status), x.status === 'success' ? 'success' : 'danger') }], empty: { ic: 'wallet', title: 'No transactions', text: '' } });
    if (tab === 'refunds') t = mountTable(el, { load: (p) => api('/admin/finance/refunds' + qs(p)), search: false, filters: [{ key: 'status', label: 'All', options: [['requested', 'Requested'], ['processed', 'Processed'], ['rejected', 'Rejected']] }],
      columns: [{ label: 'Booking', render: (f) => html`<b>${f.booking_reference}</b><span class="sub">${f.customer_name} · ${f.business_name}</span>` }, { label: 'Amount', cls: 'num', render: (f) => inr(f.amount) }, { label: 'Reason', render: (f) => f.reason || '—' }, { label: 'Requested', render: (f) => ago(f.created_at) }, { label: 'Status', render: (f) => chip(cap(f.status), { requested: 'warn', processed: 'success', rejected: 'neutral' }[f.status]) }, { label: '', cls: 'act', render: (f) => (f.status === 'requested' ? html`${rowBtn('ok', 'Approve & refund', 'btn-primary btn-sm')}${rowBtn('no', 'Reject')}` : '') }],
      actions: { ok: (f) => decideRefund(f, 'approve'), no: (f) => decideRefund(f, 'reject') }, empty: { ic: 'check', title: 'No refunds', text: 'Cancellations after payment appear here for review.' } });
    if (tab === 'payouts') t = mountTable(el, { load: (p) => api('/admin/finance/payouts' + qs(p)), search: false, filters: [{ key: 'status', label: 'All', options: [['requested', 'Requested'], ['paid', 'Paid'], ['rejected', 'Rejected']] }],
      columns: [{ label: 'Partner', render: (y) => html`<b>${y.business_name}</b><span class="sub">${y.upi_id || y.bank_masked || 'No payout account'}</span>` }, { label: 'Amount', cls: 'num', render: (y) => inr(y.amount) }, { label: 'Requested', render: (y) => dt(y.requested_at) }, { label: 'Verified', render: (y) => verified(y.verification_status) }, { label: 'Status', render: (y) => chip(cap(y.status), { requested: 'warn', paid: 'success', rejected: 'neutral' }[y.status]) }, { label: 'Reference', render: (y) => y.reference || '—' },
        { label: '', cls: 'act', render: (y) => (y.status === 'requested' ? html`${rowBtn('pay', 'Mark paid', 'btn-primary btn-sm')}${rowBtn('no', 'Reject')}` : '') }],
      actions: { pay: (y) => act2(async () => { await api(`/admin/finance/payouts/${y.id}/decide`, { method: 'POST', body: { action: 'pay' } }); toast('Payout recorded.'); t.reload(); }), no: (y) => act2(async () => { await api(`/admin/finance/payouts/${y.id}/decide`, { method: 'POST', body: { action: 'reject' } }); t.reload(); }) }, empty: { ic: 'wallet', title: 'No payouts', text: '' } });
  });
  return html`${pageHeader('Payments, commissions & refunds', 'Financial control and reconciliation.', has(ctx, 'finance') ? html`<button class="btn btn-secondary" data-act="rule">New commission rule</button>` : '')}${s.sandbox ? note('Payments run in sandbox mode. Activate real collection only after legal, tax and gateway review.', 'warn') : ''}
    <div class="grid g4 mt">${stat({ label: 'Collected from customers', value: inr(s.collected), ic: 'wallet' })}${stat({ label: 'Held in escrow', value: inr(s.escrow), ic: 'lock', tone: 'info' })}${stat({ label: 'BUZZER commission', value: inr(s.commission), ic: 'trend' })}${stat({ label: 'Owed to partners', value: inr(s.payable), ic: 'users' })}
      ${stat({ label: 'Refunded', value: inr(s.refunded), ic: 'refresh' })}${stat({ label: 'Membership revenue', value: inr(s.membership_revenue), ic: 'card' })}${stat({ label: 'Refunds to review', value: s.pending_refunds, ic: 'alert', tone: s.pending_refunds ? 'warn' : '' })}${stat({ label: 'Payouts to approve', value: s.pending_payouts, ic: 'clock', tone: s.pending_payouts ? 'warn' : '' })}</div>
    <div class="mt">${tabs([['transactions', 'Transactions'], ['refunds', 'Refunds', s.pending_refunds || null], ['payouts', 'Payouts', s.pending_payouts || null], ['rules', 'Commission rules']], tab, '#/x/finance')}</div>
    <div class="mt">${tab === 'rules' ? html`<div class="table-wrap"><table class="table"><thead><tr><th>Version</th><th class="num">Rate</th><th>Note</th><th>Effective</th></tr></thead><tbody>${s.commission_rules.map((r) => html`<tr><td data-label="Version"><b>v${r.version}</b> ${r.version === s.commission_rule.version ? chip('Current', 'lime') : ''}</td><td class="num" data-label="Rate">${r.rate}%</td><td data-label="Note">${r.note}</td><td data-label="Effective">${dt(r.effective_from)}</td></tr>`)}</tbody></table></div>` : html`<div id="tbl"></div>`}</div>`;
}

// ---------------------------------------------------------------- 14. plans
async function plans(ctx) {
  const d = await api('/admin/plans');
  const form = (p = {}) => S(field({ name: 'name', label: 'Plan name', value: p.name || '', required: true }), html`<div class="grid g2">${field({ name: 'price_month', label: 'Monthly price (₹)', type: 'number', value: p.price_month ?? '', min: 0, required: true })}${field({ name: 'price_year', label: 'Yearly price (₹)', type: 'number', value: p.price_year ?? '', min: 0, required: true })}</div>`, field({ name: 'benefits', label: 'Benefits (one per line)', type: 'textarea', rows: 5, value: (p.benefits || []).join('\n') }), p.id ? `<label class="check"><input type="checkbox" name="active" ${p.active ? 'checked' : ''}><span>Available to customers</span></label>` : '');
  const body = (x) => ({ name: x.name, price_month: x.price_month, price_year: x.price_year, benefits: x.benefits.split('\n').map((s) => s.trim()).filter(Boolean), ...(x.active !== undefined ? { active: x.active } : {}) });
  ctx.on('click', '[data-act=add]', () => modal({ title: 'New plan', body: form(), submitLabel: 'Create plan', onSubmit: async (x) => { await api('/admin/plans', { method: 'POST', body: body(x) }); toast('Plan created.'); ctx.reload(); } }));
  ctx.on('click', '[data-edit]', (e, b) => { const p = d.items.find((x) => x.id === b.dataset.edit); modal({ title: 'Edit plan', body: form(p), onSubmit: async (x) => { await api('/admin/plans/' + p.id, { method: 'PATCH', body: body(x) }); toast('Plan updated.'); ctx.reload(); } }); });
  return html`${pageHeader('Membership & plans', 'Configure customer plans and billing if monetised.', has(ctx, 'plans') ? html`<button class="btn btn-primary" data-act="add">${icon('plus', 18)} New plan</button>` : '')}
    <div class="auto-grid">${d.items.map((p) => html`<div class="card"><div class="row between"><h2>${p.name}</h2>${chip(p.active ? 'Active' : 'Hidden', p.active ? 'success' : 'neutral')}</div><div class="price-big mt">${p.price_month ? inr(p.price_month) : 'Free'}<span class="muted sm"> ${p.price_month ? '/ month' : ''}</span></div>${p.price_year ? html`<div class="muted sm">${inr(p.price_year)} / year</div>` : ''}<ul style="padding-left:18px">${p.benefits.map((b) => html`<li>${b}</li>`)}</ul><div class="row between"><span class="muted sm">${p.subscribers} active subscriber${p.subscribers === 1 ? '' : 's'}</span>${has(ctx, 'plans') ? html`<button class="btn btn-ghost btn-sm" data-edit="${p.id}">Edit</button>` : ''}</div></div>`)}</div>`;
}

// ---------------------------------------------------------------- 15. templates
async function templates(ctx) {
  const d = await api('/admin/templates');
  ctx.on('click', '[data-edit]', (e, b) => {
    const t = d.items.find((x) => x.id === b.dataset.edit);
    modal({ title: `Edit: ${t.name}`, wide: true, submitLabel: 'Save template', body: S(field({ name: 'title', label: 'Title', value: t.title, required: true }), field({ name: 'body', label: 'Message body', type: 'textarea', rows: 3, value: t.body, required: true, hint: 'Placeholders: {reference} {category} {agent} {customer} {provider} {amount} {status_label} {next} {booking} {count} {title} {reason}' }), field({ name: 'channel', label: 'Primary channel', type: 'select', value: t.channel, options: [['in_app', 'In-app'], ['whatsapp', 'WhatsApp (approved template)'], ['sms', 'SMS']] }), `<label class="check"><input type="checkbox" name="active" ${t.active ? 'checked' : ''}><span>Template active</span></label><div class="card card-soft mt"><b class="xs muted">PREVIEW</b><div id="pv"></div></div>`),
      onMount: (m) => { const pv = m.querySelector('#pv'); const draw = async () => { const r = await api('/admin/templates/preview', { method: 'POST', body: { title: m.querySelector('[name=title]').value, body: m.querySelector('[name=body]').value } }); pv.innerHTML = `<b>${esc(r.title)}</b><div class="sm">${esc(r.body)}</div>`; }; m.addEventListener('input', () => { clearTimeout(m._t); m._t = setTimeout(draw, 250); }); draw(); },
      onSubmit: async (x) => { await api('/admin/templates/' + t.id, { method: 'PATCH', body: x }); toast('Template saved. New notifications use it immediately.'); ctx.reload(); } });
  });
  ctx.on('change', '[data-active]', async (e, el) => { try { await api('/admin/templates/' + el.dataset.active, { method: 'PATCH', body: { active: el.checked } }); toast(el.checked ? 'Template enabled.' : 'Template disabled.'); } catch (err) { el.checked = !el.checked; toast(err.message, 'error'); } });
  return html`${pageHeader('Communication templates', 'Manage transactional messages and channel preferences. Events create notifications; delivery failure never blocks a request.')}
    <div class="table-wrap"><table class="table"><thead><tr><th>Event</th><th>Audience</th><th>Message</th><th>Channel</th><th>Active</th><th></th></tr></thead><tbody>${d.items.map((t) => html`<tr><td data-label="Event"><b>${t.name}</b><span class="sub">${t.code}</span></td><td data-label="Audience">${cap(t.audience)}</td><td data-label="Message"><b>${t.title}</b><span class="sub">${t.body}</span></td><td data-label="Channel">${cap(t.channel.replace('_', ' '))}</td><td data-label="Active"><label class="switch-row" style="padding:0;border:0"><span class="visually-hidden">Active</span><input type="checkbox" role="switch" data-active="${t.id}" ${t.active ? 'checked' : ''} ${has(ctx, 'templates') ? '' : 'disabled'}><i></i></label></td><td class="act">${has(ctx, 'templates') ? html`<button class="btn btn-ghost btn-sm" data-edit="${t.id}">Edit</button>` : ''}</td></tr>`)}</tbody></table></div>`;
}

// ---------------------------------------------------------------- 17. reports
async function reports(ctx) {
  const days = Number(ctx.query.days || 30);
  const d = await api('/admin/reports?days=' + days); const s = d.summary;
  ctx.on('change', '#days', (e, el) => go('/x/reports?days=' + el.value));
  ctx.on('click', '[data-act=export]', (e, b) => act(b, async () => { await download('/admin/reports/export', 'buzzer-requests.csv'); toast('Report downloaded.'); }));
  return html`${pageHeader('Reports & analytics', 'Understand demand, conversion, quality and margin.', html`<select id="days" aria-label="Period" style="width:auto">${opts([[7, 'Last 7 days'], [30, 'Last 30 days'], [90, 'Last 90 days'], [180, 'Last 180 days']], days)}</select><button class="btn btn-secondary" data-act="export">${icon('download', 18)} Export CSV</button>`)}
    <div class="grid g4">${stat({ label: 'Requests', value: s.requests, ic: 'inbox' })}${stat({ label: 'Fulfilment rate', value: s.fulfilment_rate != null ? s.fulfilment_rate + '%' : '—', ic: 'check' })}${stat({ label: 'Avg first response', value: s.first_response_hours != null ? hoursText(s.first_response_hours) : '—', ic: 'clock' })}${stat({ label: 'Quote conversion', value: s.quote_conversion != null ? s.quote_conversion + '%' : '—', ic: 'trend' })}
      ${stat({ label: 'Cancellation rate', value: s.cancellation_rate + '%', ic: 'x', tone: s.cancellation_rate > 15 ? 'warn' : '' })}${stat({ label: 'Repeat usage', value: s.repeat_usage + '%', ic: 'refresh' })}${stat({ label: 'GMV', value: inr(s.gmv), ic: 'wallet' })}${stat({ label: 'Commission margin', value: inr(s.commission), ic: 'chart' })}</div>
    <div class="card mt"><h2 class="mb">Requests over time</h2>${barChart({ labels: d.series.map((x) => x.label), series: [{ name: 'Requests', color: '#1B231E', values: d.series.map((x) => x.requests) }, { name: 'Completed', color: '#BEEB5D', values: d.series.map((x) => x.completed) }] })}</div>
    <div class="split mt"><div class="card"><h2 class="mb">By category</h2><div class="table-wrap"><table class="table"><thead><tr><th>Category</th><th class="num">Requests</th><th class="num">Completed</th><th class="num">Cancelled</th></tr></thead><tbody>${d.by_category.map((c) => html`<tr><td data-label="Category">${c.icon} ${c.name}</td><td class="num" data-label="Requests">${c.requests}</td><td class="num" data-label="Completed">${c.completed}</td><td class="num" data-label="Cancelled">${c.cancelled}</td></tr>`)}</tbody></table></div></div>
    <div class="stack"><div class="card"><h2 class="mb">By locality</h2>${hbars(d.by_locality.map((l) => ({ label: l.name || '—', value: l.requests })), { color: '#70973E' })}</div><div class="card"><h2 class="mb">By agent</h2>${hbars(d.by_agent.map((a) => ({ label: a.name, value: a.requests })))}</div></div></div>
    ${section('Top partners by booking value', html`<div class="table-wrap"><table class="table"><thead><tr><th>Partner</th><th class="num">Bookings</th><th class="num">Value</th><th class="num">Rating</th></tr></thead><tbody>${d.by_partner.map((p) => html`<tr><td data-label="Partner"><b>${p.name}</b></td><td class="num" data-label="Bookings">${p.bookings}</td><td class="num" data-label="Value">${inr(p.value)}</td><td class="num" data-label="Rating">${p.rating || '—'}</td></tr>`)}</tbody></table></div>`)}`;
}

// ---------------------------------------------------------------- 18. audit
async function audit(ctx) {
  ctx.on('click', '[data-act=export]', (e, b) => act(b, async () => { await download('/admin/audit/export', 'buzzer-audit-log.csv'); toast('Audit log downloaded (this export is itself logged).'); }));
  ctx.after(async () => { const first = await api('/admin/audit?page_size=1'); mountTable(ctx.view.querySelector('#tbl'), {
    load: (p) => api('/admin/audit' + qs(p)), search: 'Search action, entity or detail', pageSize: 15, filters: [{ key: 'action', label: 'All actions', options: first.actions.map((a) => [a, a]) }, { key: 'entity_type', label: 'All entities', options: ['request', 'quotation', 'booking', 'provider', 'user', 'category', 'refund', 'payout', 'settings', 'workflow', 'complaint'].map((x) => [x, x]) }],
    columns: [{ label: 'When', render: (l) => html`${dt(l.created_at)}<span class="sub">${ago(l.created_at)}</span>` }, { label: 'Actor', render: (l) => html`${l.actor_name || 'System'}<span class="sub">${l.actor_role || ''}</span>` }, { label: 'Action', render: (l) => html`<code>${l.action}</code>` }, { label: 'Entity', render: (l) => html`${l.entity_type || '—'}<span class="sub">${l.entity_id ? String(l.entity_id).slice(0, 8) : ''}</span>` }, { label: 'Detail', render: (l) => html`<span class="sm">${l.detail ? String(l.detail).slice(0, 90) : ''}</span>` }, { label: 'IP', render: (l) => l.ip || '—' }],
    empty: { ic: 'lock', title: 'No audit entries match', text: '' },
  }); });
  return html`${pageHeader('Audit logs & security', 'Trace sensitive access and administrative changes. Entries are append-only.', html`<button class="btn btn-secondary" data-act="export">${icon('download', 18)} Export CSV</button>`)}<div id="tbl"></div>`;
}

// ---------------------------------------------------------------- 19. settings
async function settings(ctx) {
  const d = await api('/admin/settings');
  ctx.submit('#f-set', async (x) => { const body = {}; d.settings.forEach((s) => { body[s.key] = x[s.key]; }); await api('/admin/settings', { method: 'PUT', body }); toast('Settings saved and audited.'); ctx.reload(); });
  ctx.on('click', '[data-test]', (e, b) => act(b, async () => { const r = await api(`/admin/integrations/${b.dataset.test}/test`, { method: 'POST' }); toast(r.message); ctx.reload(); }));
  const tone = { connected: 'success', sandbox: 'info', degraded: 'warn', disconnected: 'danger' };
  return html`${pageHeader('System settings & integrations', 'Manage platform configuration and service health.')}
    <div class="split"><form id="f-set" class="card" novalidate><h2 class="mb">Platform settings</h2>${d.settings.map((s) => field({ name: s.key, label: s.label || s.key, value: s.value, hint: cap(s.group_name) }))}<div class="form-error" role="alert" hidden></div><button class="btn btn-primary" type="submit">Save settings</button></form>
    <div class="card"><h2 class="mb">Integrations & service health</h2>${d.integrations.map((i) => html`<div class="list-item"><div class="grow"><b>${i.name}</b> ${chip(cap(i.status), tone[i.status])}<div class="muted sm">${i.notes}</div><div class="muted xs">Checked ${i.last_checked_at ? ago(i.last_checked_at) : 'never'}</div></div><button class="btn btn-ghost btn-sm" data-test="${i.id}">Test</button></div>`)}<p class="muted xs mt">Environment: <b>${d.environment}</b>. Secrets are read from the environment, never stored in source or in this database.</p></div></div>
    ${section('Role & permission matrix', html`<div class="table-wrap"><table class="table"><thead><tr><th>Permission</th>${Object.keys(d.roles).map((r) => html`<th class="center">${cap(r)}</th>`)}</tr></thead><tbody>${d.permissions.map((p) => html`<tr><td data-label="Permission"><b>${p}</b></td>${Object.entries(d.roles).map(([r, ps]) => html`<td class="center" data-label="${cap(r)}">${ps.includes('*') || ps.includes(p) ? html`<span style="color:var(--ok)">${icon('check', 18)}</span>` : html`<span class="muted">—</span>`}</td>`)}</tr>`)}</tbody></table></div><p class="muted sm mt">Plus record-level checks: customers see their own records, agents see assigned work, partners see only leads they were invited to.</p>`)}`;
}

// ---------------------------------------------------------------- 20. help centre
async function help(ctx) {
  const d = await api('/admin/help');
  const form = (a = {}) => S(field({ name: 'title', label: 'Title', value: a.title || '', required: true }), html`<div class="grid g2">${field({ name: 'topic', label: 'Topic', value: a.topic || 'General' })}${field({ name: 'audience', label: 'Audience', type: 'select', value: a.audience || 'customer', options: [['customer', 'Customers'], ['partner', 'Partners'], ['all', 'Everyone']] })}</div>`, field({ name: 'body', label: 'Article', type: 'textarea', rows: 6, value: a.body || '', required: true }), `<label class="check"><input type="checkbox" name="published" ${a.published !== 0 ? 'checked' : ''}><span>Published</span></label>`);
  ctx.on('click', '[data-act=add]', () => modal({ title: 'New article', wide: true, body: form(), submitLabel: 'Publish', onSubmit: async (x) => { await api('/admin/help', { method: 'POST', body: x }); toast('Article saved.'); ctx.reload(); } }));
  ctx.on('click', '[data-edit]', (e, b) => { const a = d.items.find((x) => x.id === b.dataset.edit); modal({ title: 'Edit article', wide: true, body: form(a), onSubmit: async (x) => { await api('/admin/help/' + a.id, { method: 'PATCH', body: x }); toast('Article updated.'); ctx.reload(); } }); });
  ctx.on('click', '[data-del]', async (e, b) => { const r = await confirmDialog({ title: 'Delete this article?', message: 'This cannot be undone.', confirmLabel: 'Delete', danger: true }); if (r) { await api('/admin/help/' + b.dataset.del, { method: 'DELETE' }); toast('Deleted.'); ctx.reload(); } });
  return html`${pageHeader('Content & help centre', 'Manage customer-facing guidance and FAQs.', has(ctx, 'content') ? html`<button class="btn btn-primary" data-act="add">${icon('plus', 18)} New article</button>` : '')}
    <div class="table-wrap"><table class="table"><thead><tr><th>Article</th><th>Topic</th><th>Audience</th><th>Status</th><th>Updated</th><th></th></tr></thead><tbody>${d.items.map((a) => html`<tr><td data-label="Article"><b>${a.title}</b><span class="sub">${a.body.slice(0, 90)}…</span></td><td data-label="Topic">${a.topic}</td><td data-label="Audience">${cap(a.audience)}</td><td data-label="Status">${chip(a.published ? 'Published' : 'Draft', a.published ? 'success' : 'neutral')}</td><td data-label="Updated">${ago(a.updated_at)}</td><td class="act">${has(ctx, 'content') ? html`<button class="btn btn-ghost btn-sm" data-edit="${a.id}">Edit</button><button class="icon-btn" data-del="${a.id}" aria-label="Delete ${a.title}">${icon('trash', 18)}</button>` : ''}</td></tr>`)}</tbody></table></div>`;
}

export const routes = [
  ['/x/home', home], ['/x/users', users], ['/x/agents', agents], ['/x/assignment', assignment], ['/x/partners', partners], ['/x/verification', verification], ['/x/categories', categories],
  ['/x/workflows', workflows], ['/x/requests', requests], ['/x/oversight', oversight], ['/x/jobs', jobsPage], ['/x/finance', finance], ['/x/plans', plans], ['/x/templates', templates],
  ['/x/complaints', complaintsPage], ['/x/reports', reports], ['/x/audit', audit], ['/x/settings', settings], ['/x/help', help],
];
